// TestLibraryDescriptionRoundtrip covers web-ui-phase-3 D8: the description
// column exists via an idempotent migration (safe on fresh AND pre-existing
// DBs), CreateLibrary persists it (optional trailing arg), and every library
// read round-trips it.
func TestLibraryDescriptionRoundtrip(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	t.Run("create_with_description", func(t *testing.T) {
		id, err := s.CreateLibrary(ctx, "tv", "/data/desc", "With Description", "Seasonal shows")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		got, err := s.GetLibrary(ctx, id)
		if err != nil {
			t.Fatalf("GetLibrary: %v", err)
		}
		if got.Description != "Seasonal shows" {
			t.Fatalf("GetLibrary.Description = %q, want %q", got.Description, "Seasonal shows")
		}
	})

	t.Run("create_without_description_defaults_empty", func(t *testing.T) {
		id, err := s.CreateLibrary(ctx, "tv", "/data/no-desc", "No Description")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		got, err := s.GetLibrary(ctx, id)
		if err != nil {
			t.Fatalf("GetLibrary: %v", err)
		}
		if got.Description != "" {
			t.Fatalf("GetLibrary.Description = %q, want \"\" (column default)", got.Description)
		}
	})

	t.Run("list_roundtrips_description", func(t *testing.T) {
		libs, err := s.ListLibraries(ctx)
		if err != nil {
			t.Fatalf("ListLibraries: %v", err)
		}
		byRoot := map[string]string{}
		for _, l := range libs {
			byRoot[l.RootPath] = l.Description
		}
		if byRoot["/data/desc"] != "Seasonal shows" || byRoot["/data/no-desc"] != "" {
			t.Fatalf("ListLibraries descriptions = %v", byRoot)
		}
	})

	// The pre-existing-DB path of the migration: a database created BEFORE the
	// description column (dropped here) must gain it back on the next Open,
	// with existing rows reading as "", and a further Open must stay safe.
	t.Run("migration_on_preexisting_db", func(t *testing.T) {
		dsn := filepath.Join(t.TempDir(), "legacy.db")
		legacy, err := Open(context.Background(), dsn)
		if err != nil {
			t.Fatalf("Open legacy: %v", err)
		}
		id, err := legacy.CreateLibrary(ctx, "tv", "/data/legacy", "Legacy")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		if _, err := legacy.db.ExecContext(ctx, "ALTER TABLE libraries DROP COLUMN description"); err != nil {
			t.Fatalf("drop description (simulate pre-phase-3 DB): %v", err)
		}
		if err := legacy.Close(); err != nil {
			t.Fatalf("Close legacy: %v", err)
		}
		reopened, err := Open(context.Background(), dsn)
		if err != nil {
			t.Fatalf("re-Open (additive migration): %v", err)
		}
		defer reopened.Close()
		// Re-running Open on the ALREADY-migrated database must not error
		// (the guarded ALTER no-ops) — INV-idempotent-migration.
		again, err := Open(context.Background(), dsn)
		if err != nil {
			t.Fatalf("second re-Open (idempotent migration): %v", err)
		}
		if err := again.Close(); err != nil {
			t.Fatalf("Close after second re-Open: %v", err)
		}
		got, err := reopened.GetLibrary(ctx, id)
		if err != nil {
			t.Fatalf("GetLibrary after migration: %v", err)
		}
		if got.Description != "" {
			t.Fatalf("migrated row Description = %q, want \"\"", got.Description)
		}
	})
}

// TestLibraryStreamsEnabledRoundtrip covers packaged-playback D-8: the
// streams_enabled gate column exists via an idempotent migration, every
// library defaults ON (packaging permitted — the rollback knob), and
// UpdateLibrary flips it per library while leaving it untouched when the
// pointer is nil.
func TestLibraryStreamsEnabledRoundtrip(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	t.Run("create_defaults_enabled", func(t *testing.T) {
		id, err := s.CreateLibrary(ctx, "tv", "/data/streams-default", "Default Gate")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		got, err := s.GetLibrary(ctx, id)
		if err != nil {
			t.Fatalf("GetLibrary: %v", err)
		}
		if !got.StreamsEnabled {
			t.Fatalf("GetLibrary.StreamsEnabled = false, want true (column default ON)")
		}
	})

	t.Run("patch_flips_gate_off_then_on", func(t *testing.T) {
		id, err := s.CreateLibrary(ctx, "tv", "/data/streams-flip", "Flip Gate")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		off := false
		got, err := s.UpdateLibrary(ctx, id, nil, nil, &off)
		if err != nil {
			t.Fatalf("UpdateLibrary(off): %v", err)
		}
		if got.StreamsEnabled {
			t.Fatalf("UpdateLibrary(off).StreamsEnabled = true, want false")
		}
		// A nil pointer leaves the gate untouched (partial-update contract).
		got, err = s.UpdateLibrary(ctx, id, nil, nil, nil)
		if err != nil {
			t.Fatalf("UpdateLibrary(nil): %v", err)
		}
		if got.StreamsEnabled {
			t.Fatalf("UpdateLibrary(nil).StreamsEnabled = true, want false (nil = unchanged)")
		}
		on := true
		got, err = s.UpdateLibrary(ctx, id, nil, nil, &on)
		if err != nil {
			t.Fatalf("UpdateLibrary(on): %v", err)
		}
		if !got.StreamsEnabled {
			t.Fatalf("UpdateLibrary(on).StreamsEnabled = false, want true")
		}
	})

	t.Run("list_roundtrips_gate", func(t *testing.T) {
		libs, err := s.ListLibraries(ctx)
		if err != nil {
			t.Fatalf("ListLibraries: %v", err)
		}
		byRoot := map[string]bool{}
		for _, l := range libs {
			byRoot[l.RootPath] = l.StreamsEnabled
		}
		if !byRoot["/data/streams-default"] || !byRoot["/data/streams-flip"] {
			t.Fatalf("ListLibraries gates = %v, want both enabled", byRoot)
		}
	})
}
